pairs.forEach(c=>add('letters',3,c==='Z'?'The letter after Y':`The letter before ${String.fromCharCode(c.charCodeAt(0)+1)}`,c,'Alphabet neighbours',`Think of the alphabet in order.`,c==='Z'?'Which letter comes after Y?':`Which letter comes before ${String.fromCharCode(c.charCodeAt(0)+1)}?`));
['AB','CD','EF','GH','JK','LM','NP','QR','ST','UV','WX','YZ','BP','DT','GV','MN','AE','EI','IO','OU'].forEach(code=>add('letters',2,`Spell the code: ${code.split('').join(' – ')}`,code,'Two-letter codes',`${code.length} capital letters in order.`,code.split('').join('. ')));
